svg.script:
(function(){var card=document.currentScript.parentNode;card.classList.remove("is-flow-active");
      var reducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)');
      var observer, loopTimer, inView = false, running = false, completed = 0;
      var animationName = 'feeds-arrive';
      var pulseCount = card.querySelectorAll('.feeds-arrival').length;
      function start(replay) {
        if (running || reducedMotion.matches) return;
        clearTimeout(loopTimer);
        running = true;
        completed = 0;
        if (replay) {
          card.classList.add('is-flow-reset');
          card.classList.remove('is-flow-active');
          // Commit the starting artwork before restarting the CSS animations.
          void card.getBoundingClientRect().width;
          card.classList.remove('is-flow-reset');
          void card.getBoundingClientRect().width;
        }
        card.classList.add('is-flow-active');
      }
      function update() {
        if (reducedMotion.matches) {
          running = false;
          clearTimeout(loopTimer);
          card.classList.remove('is-flow-active');
          return;
        }
        // Retain the active class for the entire sequence, even after leaving.
        if (running) return;
        if (inView) {
          if (card.classList.contains('is-flow-active')) return;
          start(false);
        } else card.classList.remove('is-flow-active');
      }
      card.addEventListener('pointerenter', function (event) {
        if (event.pointerType !== 'touch') start(true);
      });
      card.addEventListener('focus', function () {
        if (card.matches(':focus-visible')) start(true);
      });
      card.addEventListener('animationend', function (event) {
        if (event.animationName !== animationName || !running) return;
        if (++completed === pulseCount) {
          running = false;
          if (inView && !reducedMotion.matches) {
            loopTimer = setTimeout(function () {
              if (inView && !reducedMotion.matches) start(true);
            }, 700);
          } else update();
        }
      });
      function configure() {
        clearTimeout(loopTimer);
        if (observer) observer.disconnect();
        inView = false;
        if (!reducedMotion.matches && 'IntersectionObserver' in window) {
          observer = new IntersectionObserver(function (entries) {
            var entry = entries[0];
            if (entry.intersectionRatio >= 0.6) inView = true;
            else if (!entry.isIntersecting) inView = false;
            update();
          }, { threshold: [0, 0.6], rootMargin: '-64px 0px 0px 0px' });
          observer.observe(card);
        }
        update();
      }
      reducedMotion.addEventListener('change', configure);
      configure();

})();
